// Extract payload or default
let data = msg.payload || {};

// Machine details
let machine = data.machine_name || (msg.req.params && msg.req.params.machine) || "MC-UNKNOWN";
let line = data.line_name || "Line-01";
let value = data.value !== undefined ? String(data.value).trim() : "";
let prevValue = data.previous_value !== undefined && data.previous_value !== null ? String(data.previous_value).trim() : null;
let timestamp = data.timestamp || new Date().toISOString().slice(0, 19).replace('T', ' ');

// Basic validation
if (!value) {
    msg.statusCode = 400;
    msg.payload = {
        status: "ERROR",
        message: "Value field is required and cannot be empty"
    };
    node.error("Received empty OCR value from machine: " + machine, msg);
    return [msg, null, null];
}

msg.ocr_data = {
    machine_name: machine,
    line_name: line,
    value: value,
    previous_value: prevValue,
    timestamp: timestamp
};

// 1. Maintain in-memory flow cache for instant GET verification without database
let memoryLogs = flow.get("ocr_memory_logs") || [];
memoryLogs.unshift({
    id: memoryLogs.length + 1,
    machine_name: machine,
    line_name: line,
    detected_value: value,
    previous_value: prevValue,
    captured_at: timestamp,
    received_at: new Date().toISOString().slice(0, 19).replace('T', ' ')
});
if (memoryLogs.length > 500) {
    memoryLogs = memoryLogs.slice(0, 500);
}
flow.set("ocr_memory_logs", memoryLogs);

// 2. Maintain machine live status map
let statusMap = flow.get("machine_status_map") || {};
let count = (statusMap[machine] && statusMap[machine].total_count) ? statusMap[machine].total_count + 1 : 1;
statusMap[machine] = {
    machine_name: machine,
    line_name: line,
    latest_value: value,
    previous_value: prevValue,
    last_updated: timestamp,
    total_count: count
};
flow.set("machine_status_map", statusMap);

// Output 1: Immediate HTTP Response
let responseMsg = {
    _msgid: msg._msgid,
    req: msg.req,
    res: msg.res,
    statusCode: 200,
    payload: {
        status: "SUCCESS",
        machine_name: machine,
        line_name: line,
        detected_value: value,
        previous_value: prevValue,
        received_at: timestamp
    }
};

// Output 2: MySQL Insert into Historical Logs
let insertLogMsg = {
    _msgid: msg._msgid,
    topic: "INSERT INTO machine_ocr_logs (machine_name, line_name, detected_value, previous_value, captured_at) VALUES (?, ?, ?, ?, ?);",
    payload: [machine, line, value, prevValue, timestamp],
    ocr_data: msg.ocr_data
};

// Output 3: MySQL Upsert into Live Current Status
let upsertStatusMsg = {
    _msgid: msg._msgid,
    topic: "INSERT INTO machine_current_status (machine_name, line_name, latest_value, previous_value, last_updated) VALUES (?, ?, ?, ?, ?) ON DUPLICATE KEY UPDATE latest_value=VALUES(latest_value), previous_value=VALUES(previous_value), last_updated=VALUES(last_updated);",
    payload: [machine, line, value, prevValue, timestamp],
    ocr_data: msg.ocr_data
};

node.status({ fill: "green", shape: "dot", text: machine + " (" + line + "): " + value });

return [responseMsg, insertLogMsg, upsertStatusMsg];

let logs = flow.get("ocr_memory_logs") || [];
let statusMap = flow.get("machine_status_map") || {};
let query = msg.req.query || {};
let targetMachine = query.machine;

let targetLogs = targetMachine ? logs.filter(l => l.machine_name.toLowerCase() === targetMachine.toLowerCase()) : logs;

let totalReceived = targetLogs.length;
let latestReading = targetLogs.length > 0 ? targetLogs[0] : null;
let earliestReading = targetLogs.length > 0 ? targetLogs[targetLogs.length - 1] : null;

msg.payload = {
    status: "SUCCESS",
    verification_check: "DATA_INTEGRITY_AUDIT",
    filter_machine: targetMachine || "ALL",
    summary: {
        total_readings_received: totalReceived,
        latest_value: latestReading ? latestReading.detected_value : null,
        latest_timestamp: latestReading ? latestReading.captured_at : null,
        earliest_timestamp: earliestReading ? earliestReading.captured_at : null,
        machines_reporting: Object.keys(statusMap)
    },
    audit_result: totalReceived > 0 ? "DATA_LOGGED_AND_VERIFIED" : "AWAITING_FIRST_LOG",
    note: "Compare 'total_readings_received' with client ocr_log.csv row count to verify 0 missed.",
    timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ')
};

return msg;

let statusMap = flow.get("machine_status_map") || {};
let now = Date.now();

let list = Object.values(statusMap).map(m => {
    let lastTime = new Date(m.last_updated).getTime();
    let diffSec = Math.round((now - lastTime) / 1000);
    return {
        machine_name: m.machine_name,
        line_name: m.line_name,
        latest_value: m.latest_value,
        previous_value: m.previous_value,
        last_updated: m.last_updated,
        total_readings: m.total_count,
        status: (diffSec > 300 ? "WARNING_STALE" : "ONLINE_ACTIVE"),
        seconds_since_last_seen: isNaN(diffSec) ? 0 : diffSec
    };
});

msg.payload = {
    status: "SUCCESS",
    active_machines_count: list.length,
    machines: list,
    timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ')
};

return msg;

let logs = flow.get("ocr_memory_logs") || [];
let query = msg.req.query || {};
let machine = query.machine;
let limit = parseInt(query.limit) || 50;

let filtered = logs;
if (machine) {
    filtered = filtered.filter(l => l.machine_name.toLowerCase() === machine.toLowerCase());
}

let result = filtered.slice(0, limit);

msg.payload = {
    status: "SUCCESS",
    query: {
        machine: machine || "ALL",
        limit: limit
    },
    total_stored_in_cache: filtered.length,
    returned_count: result.length,
    logs: result,
    timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ')
};

return msg;

let machine = (msg.req.query && msg.req.query.machine) || "MC-04";
msg.target_machine = machine;
msg.topic = "SELECT COUNT(*) as total_db_records, MAX(captured_at) as last_db_captured_at, (SELECT detected_value FROM machine_ocr_logs WHERE machine_name = ? ORDER BY captured_at DESC, id DESC LIMIT 1) as last_db_value FROM machine_ocr_logs WHERE machine_name = ?;";
msg.payload = [machine, machine];
return msg;

let rows = msg.payload || [];
let row = rows.length > 0 ? rows[0] : {};
msg.payload = {
    status: "SUCCESS",
    source: "MYSQL_DATABASE_SELECT_QUERY",
    machine_name: msg.target_machine,
    total_db_records: row.total_db_records !== undefined ? Number(row.total_db_records) : 0,
    last_db_captured_at: row.last_db_captured_at || null,
    last_db_value: row.last_db_value || null,
    audit_note: "Check if client CSV has rows after last_db_captured_at. Any newer rows need to be sent.",
    timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ')
};
return msg;

let machine = (msg.req.query && msg.req.query.machine) || "";
let limit = parseInt(msg.req.query && msg.req.query.limit) || 20;
msg.query_meta = { machine: machine || "ALL", limit: limit };
if (machine) {
    msg.topic = "SELECT id, machine_name, line_name, detected_value, previous_value, DATE_FORMAT(captured_at, '%Y-%m-%d %H:%i:%s') as captured_at, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as created_at FROM machine_ocr_logs WHERE machine_name = ? ORDER BY captured_at DESC, id DESC LIMIT ?;";
    msg.payload = [machine, limit];
} else {
    msg.topic = "SELECT id, machine_name, line_name, detected_value, previous_value, DATE_FORMAT(captured_at, '%Y-%m-%d %H:%i:%s') as captured_at, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as created_at FROM machine_ocr_logs ORDER BY captured_at DESC, id DESC LIMIT ?;";
    msg.payload = [limit];
}
return msg;

let rows = msg.payload || [];
msg.payload = {
    status: "SUCCESS",
    source: "MYSQL_DATABASE_SELECT_QUERY",
    query: msg.query_meta,
    returned_records: rows.length,
    logs: rows,
    timestamp: new Date().toISOString().slice(0, 19).replace('T', ' ')
};
return msg;
